#!/bin/bash
# Generated by scripts/export-killercoda.ts. Passes (exit 0) when the named checks of lab-m14-expose-shelf pass.
# Environment overrides, for local tests: SHELF_BIN, KUBECONFIG, SHELF_MARKER_DIR, SHELF_COURSE_DIR, SHELF_LABS_DIR.
LAB=lab-m14-expose-shelf
CHECKS="db-reachable api-reachable web-reachable chain-works"
MARK="${SHELF_MARKER_DIR:-/tmp}"
SHELF="${SHELF_BIN:-/usr/local/bin/shelf}"
[ -f "$MARK/shelf-failed" ] && { echo "Setup failed: $(cat "$MARK/shelf-failed"). See /tmp/shelf-setup.log." >&2; exit 1; }
[ -f "$MARK/shelf-ready" ] || { echo "Setup is not finished. Wait for RESULT: ready in the first terminal, then click Check again." >&2; exit 1; }
export KUBECONFIG="${KUBECONFIG:-/root/.kube/config}"
cd "${SHELF_COURSE_DIR:-/root/course}" || { echo "The course folder is missing." >&2; exit 1; }
kubectl --context kind-reconcile --request-timeout=10s get nodes >/dev/null 2>&1 || { echo "The cluster is not reachable. Create it first (shelf up), and wait for the node to be Ready." >&2; exit 1; }
# Only this step's checks run, and each wait is capped at 30 s: the lab's own checks.yaml is replaced in a temporary copy of the labs folder.
LABS="${SHELF_LABS_DIR:-${SHELF_COURSE_DIR:-/root/course}/labs}"
T=$(mktemp -d) || { echo "Cannot make a temporary folder." >&2; exit 1; }
trap '[ -n "$T" ] && rm -rf "$T"' EXIT
for e in "$LABS"/*; do n=${e##*/}; [ "$n" = "$LAB" ] || ln -s "$e" "$T/$n"; done
cp -R "$LABS/$LAB" "$T/$LAB"
cat > "$T/$LAB/checks.yaml" <<'KILLERCODA_CHECKS'
apiVersion: labs.reconcile.example/v1
kind: LabChecks
lab: lab-m14-expose-shelf
checks:
  - id: db-reachable
    describe: A connection from the probe Pod to shelf-db on port 5432 succeeds
    kubectl:
      - exec
      - shelf-probe
      - -n
      - shelf
      - --
      - nc
      - -zw
      - "3"
      - shelf-db.shelf.svc.cluster.local.
      - "5432"
    expect:
      eventually:
        timeout: 30s
        interval: 3s
        expect:
          exitCode: 0
    hint: From the probe Pod, run `kubectl exec shelf-probe --namespace shelf -- nc -zw 3 shelf-db.shelf.svc.cluster.local. 5432`. A refusal means no endpoint behind the Service, or the wrong target port.
  - id: api-reachable
    describe: A request from the probe Pod to shelf-api on port 8081 succeeds
    kubectl:
      - exec
      - shelf-probe
      - -n
      - shelf
      - --
      - wget
      - -qO-
      - -T
      - "3"
      - http://shelf-api.shelf.svc.cluster.local.:8081/healthz
    expect:
      eventually:
        timeout: 30s
        interval: 3s
        expect:
          exitCode: 0
    hint: Run `kubectl exec shelf-probe --namespace shelf -- wget -qO- -T 3 http://shelf-api.shelf.svc.cluster.local.:8081/healthz`. `Connection refused` with endpoints in the list means a wrong target port. `Connection refused` with an empty list means the selector.
  - id: web-reachable
    describe: A request from the probe Pod to shelf-web on port 80 succeeds
    kubectl:
      - exec
      - shelf-probe
      - -n
      - shelf
      - --
      - wget
      - -qO-
      - -T
      - "3"
      - http://shelf-web.shelf.svc.cluster.local.:80/healthz
    expect:
      eventually:
        timeout: 30s
        interval: 3s
        expect:
          exitCode: 0
    hint: Run `kubectl exec shelf-probe --namespace shelf -- wget -qO- -T 3 http://shelf-web.shelf.svc.cluster.local.:80/healthz`. Port 80 is the Service port, and the Service sends it to 8080.
  - id: chain-works
    describe: A request through shelf-web reaches the api, which reads the books from the database
    kubectl:
      - exec
      - shelf-probe
      - -n
      - shelf
      - --
      - wget
      - -qO-
      - -T
      - "5"
      - http://shelf-web.shelf.svc.cluster.local.:80/api/books
    expect:
      eventually:
        timeout: 30s
        interval: 3s
        expect:
          matches: '"total":[1-9]'
    hint: The web server forwards `/api/books` to the Service shelf-api, and the api reads the books from the Service shelf-db. If the answer is an error, find the first Service in that chain that fails the checks above. A `502` from the web server means that it cannot reach the api.
KILLERCODA_CHECKS
out=$(SHELF_LABS_DIR="$T" timeout 60 "$SHELF" verify "$LAB" 2>&1); rc=$?
if [ "$rc" -eq 124 ]; then echo "The checks took too long. Wait a few seconds and click Check again." >&2; exit 1; fi
if [ "$rc" -ge 2 ]; then echo "$out" >&2; exit 1; fi
bad=0
for id in $CHECKS; do
  printf '%s\n' "$out" | grep -Eq "^(PASS|SKIP) $id " && continue
  bad=1; printf '%s\n' "$out" | grep -E -A2 "^FAIL $id "
done
[ "$bad" -eq 0 ] || echo "If you just applied a change, it may still be rolling out: wait a few seconds and click Check again." >&2
exit "$bad"
